def test_limit_server():
    with patch("os.environ.get", return_value="allowed-server"):
        scheduler = OlBlockingScheduler()

        @limit_server(["allowed-server"], scheduler)
        @scheduler.scheduled_job("interval", seconds=60)
        def sample_job():
            pass

        sample_job()
        assert scheduler.get_job("sample_job") is not None


    with patch("os.environ.get", return_value="other-server"):
        scheduler = OlBlockingScheduler()

        @limit_server(["allowed-server"], scheduler)
        @scheduler.scheduled_job("interval", seconds=60)
        def sample_job():
            pass

        sample_job()
        assert scheduler.get_job("sample_job") is None

    with patch("os.environ.get", return_value="allowed-server0"):
        scheduler = OlBlockingScheduler()

        @limit_server(["allowed-server*"], scheduler)
        @scheduler.scheduled_job("interval", seconds=60)
        def sample_job():
            pass

        sample_job()
        assert scheduler.get_job("sample_job") is not None


def test_async_scheduler_host_scope_and_job_id():
    assert issubclass(OlAsyncIOScheduler, AsyncIOScheduler)
    for host, allowed, registered in [
        ('allowed-server', ['allowed-server'], True),
        ('allowed-server0', ['allowed-server*'], True),
        ('ol-web0.us.archive.org', ['ol-web0'], True),
        ('other-server', ['allowed-server'], False),
        ('allowed-server-extra', ['allowed-server'], False),
    ]:
        with patch('os.environ.get', return_value=host):
            scheduler = OlAsyncIOScheduler()

            @limit_server(allowed, scheduler)
            @scheduler.scheduled_job('interval', seconds=60)
            async def sample_job():
                pass

            assert (scheduler.get_job('sample_job') is not None) is registered


def test_get_service_ip():
    with patch('subprocess.run') as run:
        run.return_value.stdout = '172.18.0.3\n'
        assert get_service_ip('web_haproxy') == '172.18.0.3'
        assert run.call_args.args[0][-1] == 'openlibrary-web_haproxy-1'

    with patch("os.environ.get", return_value="ol-web0.us.archive.org"):
        scheduler = OlBlockingScheduler()

        @limit_server(["ol-web0"], scheduler)
        @scheduler.scheduled_job("interval", seconds=60)
        def sample_job():
            pass

        sample_job()
        assert scheduler.get_job("sample_job") is not None
